{
  "interpretation": {
    "name": "TightenVariantOnLine2AndReturnTool",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Tighten the fasteners of variant F30 on line 2 at station st2 with the shared nutrunner NR7, then return the tool to the crib.",
    "constraints": [
      "The tool must be reserved before any use and released at the end",
      "The tool must be at the station (transport-tool to 'station' completed) before configure-tool and tighten-fasteners",
      "The tightening program comes only from get-program for the variant and is never written as a literal",
      "The tightening must be evaluated and recorded for traceability",
      "transport-tool Steps must be delegated to the executor agvexecutor",
      "The tool is returned to the crib after tightening"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "one-off, for the current request",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "tighten-f30-line2-and-return-tool",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "deliver-tool",
        "steps": [
          {
            "name": "reserve-tool-step",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "get-program-step",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "deliver-tool",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-to-station-step",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve-tool-step"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "return-tool",
        "steps": [
          {
            "name": "configure-tool-step",
            "service": "configure-tool",
            "next": ["tighten-fasteners-step"],
            "dep": ["get-program-step", "reserve-tool-step"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-fasteners-step",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["configure-tool-step", "reserve-tool-step"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "return-tool",
        "next": "quality",
        "steps": [
          {
            "name": "transport-to-crib-step",
            "service": "transport-tool",
            "next": ["release-tool-step"],
            "dep": ["reserve-tool-step"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release-tool-step",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve-tool-step"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "quality",
        "next": null,
        "steps": [
          {
            "name": "evaluate-tightening-step",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-fasteners-step", "get-program-step"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record-tightening-step",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-fasteners-step"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
